#!/usr/bin/env bash
# OVHcloud Game Panel: CoD4 "Command line" card (Server settings > Game config), for LinuxGSM cod4server.
# Fields: sv_authtoken, r_xassetnum (Materials/Xanims/Xmodels), fs_game, rcon_password.
# The RCON password goes straight into the start command; the auth token is stored in config-lgsm/<server>/secrets-common.cfg.
# Replaces the older "Mod" card (gp-cod4-mod.sh). Run again after a panel update.
set -euo pipefail
APP_ROOT="${GP_APP_ROOT:-/opt/gamepanel}"
SRC="$APP_ROOT/app"
DEPLOY="$APP_ROOT/deploy"
C="$SRC/frontend/components"
SECTION="$C/serverSettings/Cod4ModSection.tsx"
[[ $EUID -eq 0 ]] || { echo "Pokreni kao root: sudo bash $0"; exit 1; }
[[ -d $SRC/frontend && -f $DEPLOY/compose.yml ]] || { echo "Game Panel nije pronađen u $APP_ROOT"; exit 1; }
if [[ -f $SECTION ]] && grep -q "lives only in the command line" "$SECTION"; then echo "Već je instalirano."; exit 0; fi
command -v patch >/dev/null || { apt-get update -qq && apt-get install -y -qq patch; }
backup="$APP_ROOT/cod4cmd-backup-$(date +%Y%m%d-%H%M%S)"; mkdir -p "$backup"
cp -p "$C/GameConfigTab.tsx" "$C/ServerSettingsModal.tsx" "$backup/"
had_section=0; [[ -f $SECTION ]] && { cp -p "$SECTION" "$backup/"; had_section=1; }
cd "$SRC"
if ! grep -q Cod4ModSection "$C/GameConfigTab.tsx"; then
  tmp=$(mktemp); echo '' | base64 -d > "$tmp"
  if ! patch -p1 --dry-run -s < "$tmp" >/dev/null; then
    echo "Ova verzija panela se razlikuje od one za koju je izmjena napravljena (1.6.0). Ništa nije promijenjeno."; rm -f "$tmp"; exit 1
  fi
  patch -p1 -s < "$tmp"; rm -f "$tmp"
fi
restore(){
  cp -p "$backup/GameConfigTab.tsx" "$backup/ServerSettingsModal.tsx" "$C/"
  if ((had_section)); then cp -p "$backup/Cod4ModSection.tsx" "$SECTION"; else rm -f "$SECTION"; fi
  echo "Greška: izmjena vraćena (kopija u $backup)." >&2
}
trap 'rc=$?; ((rc)) && restore' EXIT
echo '' | base64 -d > "$SECTION"
dc(){ docker compose --project-name gamepanel --env-file "$DEPLOY/.env" -f "$DEPLOY/compose.yml" "$@"; }
echo "Gradim novo sučelje panela (par minuta)..."
dc build frontend
dc up -d frontend
trap - EXIT
echo "Gotovo. Otvori panel (Ctrl+F5) > CoD4 server > Settings > Game config: kartica 'Command line'."
echo "Nakon nadogradnje Game Panela ponovno pokreni: sudo bash $0"
